{
  "objectives": [
    {
      "level": "primary",
      "text": "To compare the efficacy of AMG 510 versus docetaxel as assessed by progression-free survival (PFS) in previously treated subjects with KRAS p.G12C mutated non-small cell lung cancer (NSCLC)",
      "quote": "To compare the efficacy of AMG 510 versus docetaxel as assessed by progression-free survival (PFS) in previously treated subjects with KRAS p.G12C mutated non-small cell lung cancer (NSCLC)",
      "endpoints": [
        {
          "text": "Progression-free survival (PFS) - defined as time from randomization until disease progression or death from any cause, whichever occurs first for all subjects. Progression will be based on blinded independent central review (BICR) of disease response per Response Evaluation Criteria in Solid Tumors version 1.1 (RECIST v1.1).",
          "measure": "PFS",
          "timepoints_weeks": [],
          "quote": "PFS - defined as time from randomization until disease progression or death from any cause, whichever occurs first for all subjects. Progression will be based on blinded independent central review (BICR) of disease response per Response Evaluation Criteria in Solid Tumors version 1.1 (RECIST v1.1)."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To compare the efficacy of AMG 510 versus docetaxel as assessed by: Overall Survival (OS), Objective response rate (ORR)",
      "quote": "To compare the efficacy of AMG 510 versus docetaxel as assessed by: Overall Survival (OS), Objective response rate (ORR)",
      "endpoints": [
        {
          "text": "Overall survival - defined as time from randomization until death from any cause.",
          "measure": "OS",
          "timepoints_weeks": [],
          "quote": "Overall survival - defined as time from randomization until death from any cause."
        },
        {
          "text": "Objective response (complete response [CR] + partial response [PR]), assessed per RECIST v1.1. Response will be assessed by BICR. Complete response and PR require confirmatory repeat radiologic assessment at no less than 4 weeks after the original response.",
          "measure": "ORR",
          "timepoints_weeks": [],
          "quote": "Objective response (complete response [CR] + partial response [PR]), assessed per RECIST v1.1. Response will be assessed by BICR. Complete response and PR require confirmatory repeat radiologic assessment at no less than 4 weeks after the original response."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To compare patient-reported outcomes (PRO) as assessed by: European Organization for Research and Treatment of Cancer Quality-of-life Questionnaire Core 13 (EORTC QLQ-LC13) and European Organization for Research and Treatment of Cancer Quality-of-life Questionnaire Core 30 (EORTC QLQ-C30)",
      "quote": "To compare patient-reported outcomes (PRO) as assessed by: European Organization for Research and Treatment of Cancer Quality-of-life Questionnaire Core 13 (EORTC QLQ-LC13) and European Organization for Research and Treatment of Cancer Quality-of-life Questionnaire Core 30 (EORTC QLQ-C30)",
      "endpoints": [
        {
          "text": "Change from baseline (cycle 1 day 1) over time to week 12 in disease related symptoms of: Dyspnea as measured by a 4-item dyspnea domain from QLQ-C30 and QLQ-LC13; Cough as measured by QLQ-LC13; Chest Pain as measured by QLQ-LC13",
          "measure": "Change from baseline in disease related symptoms",
          "timepoints_weeks": [0, 12],
          "quote": "Change from baseline (cycle 1 day 1) over time to week 12 in disease related symptoms of: Dyspnea as measured by a 4-item dyspnea domain from QLQ-C30 and QLQ-LC13; Cough as measured by QLQ-LC13; Chest Pain as measured by QLQ-LC13"
        },
        {
          "text": "Change from baseline over time to week 12 in Physical functioning as measured by QLQ-C30; Global health status as measured by QLQ-C30",
          "measure": "Change from baseline in physical functioning and global health status",
          "timepoints_weeks": [0, 12],
          "quote": "Change from baseline over time to week 12 in Physical functioning as measured by QLQ-C30; Global health status as measured by QLQ-C30"
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To compare efficacy of AMG 510 versus docetaxel as assessed by: duration of response (DOR), time to response (TTR), and disease control rate (DCR)",
      "quote": "To compare efficacy of AMG 510 versus docetaxel as assessed by: duration of response (DOR), time to response (TTR), and disease control rate (DCR)",
      "endpoints": [
        {
          "text": "Duration of response - defined as time from first evidence of PR or CR to disease progression or death due to any cause, whichever occurs first. Progression will be based on an BICR assessment of disease response per RECIST v1.1.",
          "measure": "DOR",
          "timepoints_weeks": [],
          "quote": "Duration of response - defined as time from first evidence of PR or CR to disease progression or death due to any cause, whichever occurs first. Progression will be based on an BICR assessment of disease response per RECIST v1.1."
        },
        {
          "text": "Time to response - defined as time from randomization to first evidence of PR or CR.",
          "measure": "TTR",
          "timepoints_weeks": [],
          "quote": "Time to response - defined as time from randomization to first evidence of PR or CR."
        },
        {
          "text": "Disease control rate - defined as rate of confirmed objective response (CR or PR) + stable disease per RECIST v1.1 of at least 6 weeks measured",
          "measure": "DCR",
          "timepoints_weeks": [6],
          "quote": "Disease control rate - defined as rate of confirmed objective response (CR or PR) + stable disease per RECIST v1.1 of at least 6 weeks measured"
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To compare the safety and tolerability of AMG 510 versus docetaxel",
      "quote": "To compare the safety and tolerability of AMG 510 versus docetaxel",
      "endpoints": [
        {
          "text": "Subject incidence of treatment-emergent adverse events, treatment-related adverse events, changes in vital signs, and clinical laboratory tests.",
          "measure": "Safety and tolerability",
          "timepoints_weeks": [],
          "quote": "Subject incidence of treatment-emergent adverse events, treatment-related adverse events, changes in vital signs, and clinical laboratory tests."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To compare the effect of treatment with AMG 510 on other treatment and disease related symptoms, and health related quality of life relative to docetaxel",
      "quote": "To compare the effect of treatment with AMG 510 on other treatment and disease related symptoms, and health related quality of life relative to docetaxel",
      "endpoints": [
        {
          "text": "Change from baseline over time to week 12 for the remaining subscales for QLQ-LC13 and QLQ-C30",
          "measure": "Change from baseline in remaining subscales",
          "timepoints_weeks": [0, 12],
          "quote": "Change from baseline over time to week 12 for the remaining subscales for QLQ-LC13 and QLQ-C30"
        },
        {
          "text": "Time to deterioration for the subscales for QLQ-LC13 and QLQ-C30",
          "measure": "Time to deterioration",
          "timepoints_weeks": [],
          "quote": "Time to deterioration for the subscales for QLQ-LC13 and QLQ-C30"
        },
        {
          "text": "Summary scores at each assessment and changes from baseline of visual analogue scale (VAS) scores as measured by EuroQol-5 Dimension (EQ5D5L)",
          "measure": "EQ5D5L VAS scores",
          "timepoints_weeks": [],
          "quote": "Summary scores at each assessment and changes from baseline of visual analogue scale (VAS) scores as measured by EuroQol-5 Dimension (EQ5D5L)"
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To characterize the pharmacokinetics (PK) of AMG 510 and its major metabolites",
      "quote": "To characterize the pharmacokinetics (PK) of AMG 510 and its major metabolites",
      "endpoints": [
        {
          "text": "Pharmacokinetic (PK) parameters of AMG 510 including, but not limited to, maximum plasma concentration (Cmax), area under the plasma concentration-time curve (AUC) on Days 1 and 8, and pre-dose (trough) concentrations through cycle 4",
          "measure": "PK parameters",
          "timepoints_weeks": [0, 1, 12],
          "quote": "Pharmacokinetic (PK) parameters of AMG 510 including, but not limited to, maximum plasma concentration (Cmax), area under the plasma concentration-time curve (AUC) on Days 1 and 8, and pre-dose (trough) concentrations through cycle 4"
        }
      ]
    }
  ]
}
